import * as React from 'react'

export interface UseStandInTargetOptions {
  /** Height in px of chrome overlaying the top of the target's scroller (a
   * floating header): the target counts as away once it slips behind it,
   * while a plain intersection would call it visible the whole time it sits
   * under the frost. 0 when nothing overlays the scroller. */
  topInset?: number
  /** Visibility reports. Also called with `true` when the target detaches
   * (unmount, layout-gate collapse, route change), so a stand-in never
   * outlives its subject. */
  onInViewChange: (inView: boolean) => void
}

// The nearest scrollable ancestor is the IntersectionObserver root: the
// element clips there, not at the viewport. Falls back to the viewport for a
// document-scrolled page.
function nearestScroller(el: HTMLElement): Element | null {
  let node = el.parentElement
  while (node) {
    const { overflowY } = getComputedStyle(node)
    if (overflowY === 'auto' || overflowY === 'scroll') return node
    node = node.parentElement
  }
  return null
}

/**
 * Watches a field's primary instance and reports whether it is in view inside
 * its own scroller, so a `HeaderStandIn` can grow in while it is scrolled
 * away. Returns a callback ref -- attach it to the element wrapping the
 * primary instance. A callback ref rather than an effect because the target
 * typically mounts and unmounts with a portal or layout gate; the observer
 * attaches whenever the node appears and detaching resets the state.
 * `onInViewChange` is read through a ref, so an inline arrow does not
 * re-observe each render; changing `topInset` re-attaches with the new inset.
 */
export function useStandInTarget({
  topInset = 0,
  onInViewChange,
}: UseStandInTargetOptions): (node: HTMLElement | null) => void {
  const onChangeRef = React.useRef(onInViewChange)
  React.useEffect(() => {
    onChangeRef.current = onInViewChange
  }, [onInViewChange])

  const cleanupRef = React.useRef<(() => void) | null>(null)
  return React.useCallback(
    (node: HTMLElement | null) => {
      cleanupRef.current?.()
      cleanupRef.current = null
      if (!node) {
        onChangeRef.current(true)
        return
      }
      const root = nearestScroller(node)
      const observer = new IntersectionObserver(
        ([entry]) => onChangeRef.current(entry.isIntersecting),
        {
          root,
          rootMargin: `-${topInset}px 0px 0px 0px`,
          threshold: 0,
        },
      )
      observer.observe(node)
      // WebKitGTK (the Linux webview) fails to recompute intersections after
      // pure layout changes with an element root: a target attached inside a
      // collapsed pane (AppPanes' w-0 'auto' state) keeps its empty
      // intersection forever, even through scrolls. Re-observing on any size
      // change of the target or its scroller queues a fresh record from
      // current geometry on every engine.
      const resize = new ResizeObserver(() => {
        observer.unobserve(node)
        observer.observe(node)
      })
      resize.observe(node)
      if (root instanceof Element) resize.observe(root)
      cleanupRef.current = () => {
        observer.disconnect()
        resize.disconnect()
      }
    },
    [topInset],
  )
}
